CREATE TABLE "bracket_divisions" (
	"id" text PRIMARY KEY NOT NULL,
	"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
	"updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
	"sport_id" text NOT NULL,
	"slug" text NOT NULL,
	"label" text NOT NULL,
	CONSTRAINT "bracket_divisions_sport_id_slug_unique" UNIQUE("sport_id","slug")
);
--> statement-breakpoint
CREATE TABLE "bracket_editions" (
	"id" text PRIMARY KEY NOT NULL,
	"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
	"updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
	"format_id" text NOT NULL,
	"season_id" text NOT NULL,
	"kind" text NOT NULL,
	"status" text NOT NULL,
	"source_week_id" text NOT NULL,
	"revision" integer NOT NULL,
	"cloned_from_edition_id" text,
	"article_url" text,
	"public_note" text,
	"published_at" timestamp with time zone,
	"published_by_user_id" text,
	CONSTRAINT "bracket_editions_kind_check" CHECK ("bracket_editions"."kind" in ('projection', 'official')),
	CONSTRAINT "bracket_editions_status_check" CHECK ("bracket_editions"."status" in ('draft', 'published', 'superseded')),
	CONSTRAINT "bracket_editions_article_url_check" CHECK ("bracket_editions"."article_url" is null or "bracket_editions"."article_url" ~ '^https?://')
);
--> statement-breakpoint
CREATE TABLE "bracket_formats" (
	"id" text PRIMARY KEY NOT NULL,
	"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
	"updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
	"sport_id" text NOT NULL,
	"division_id" text,
	"key" text NOT NULL,
	"effective_from_year" integer NOT NULL,
	"effective_to_year" integer,
	"spec" jsonb NOT NULL,
	CONSTRAINT "bracket_formats_key_unique" UNIQUE("key")
);
--> statement-breakpoint
CREATE TABLE "bracket_games" (
	"id" text PRIMARY KEY NOT NULL,
	"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
	"updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
	"edition_id" text NOT NULL,
	"game_key" text NOT NULL,
	"round_key" text NOT NULL,
	"round_label" text NOT NULL,
	"side_a_slot_key" text,
	"side_b_slot_key" text,
	"side_a_from_game_key" text,
	"side_b_from_game_key" text,
	"home_side" text,
	"site_label" text,
	"status" text DEFAULT 'scheduled' NOT NULL,
	"winner_school_id" text,
	"home_score" integer,
	"away_score" integer,
	CONSTRAINT "bracket_games_edition_id_game_key_unique" UNIQUE("edition_id","game_key"),
	CONSTRAINT "bracket_games_home_side_check" CHECK ("bracket_games"."home_side" is null or "bracket_games"."home_side" in ('a', 'b')),
	CONSTRAINT "bracket_games_status_check" CHECK ("bracket_games"."status" in ('scheduled', 'final'))
);
--> statement-breakpoint
CREATE TABLE "bracket_slots" (
	"id" text PRIMARY KEY NOT NULL,
	"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
	"updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
	"edition_id" text NOT NULL,
	"slot_key" text NOT NULL,
	"seed" integer,
	"region" text,
	"show_seed" boolean NOT NULL,
	"school_id" text,
	"bid_type" text,
	"bid_label" text,
	CONSTRAINT "bracket_slots_edition_id_slot_key_unique" UNIQUE("edition_id","slot_key"),
	CONSTRAINT "bracket_slots_bid_type_check" CHECK ("bracket_slots"."bid_type" is null or "bracket_slots"."bid_type" in ('auto', 'at-large'))
);
--> statement-breakpoint
