-- Format rows are inserted from existing sports. A database with no synced sport
-- rows keeps the tables and skips these inserts.
INSERT INTO "bracket_divisions" ("id", "sport_id", "slug", "label")
SELECT gen_random_uuid()::text, "id", 'fcs', 'FCS'
FROM "sports"
WHERE "slug" = 'football'
AND NOT EXISTS (
  SELECT 1 FROM "bracket_divisions" "existing"
  JOIN "sports" "existing_sport" ON "existing_sport"."id" = "existing"."sport_id"
  WHERE "existing_sport"."slug" = 'football'
    AND "existing"."slug" = 'fcs'
);
--> statement-breakpoint
